#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# ── Windows helpers (authored: this wizard installs a Windows binary) ──────
_win2unix() { cygpath -u "$1" 2>/dev/null || printf '%s' "$1"; }
_unix2win() { cygpath -w "$1" 2>/dev/null || printf '%s' "$1"; }
_is_windows() {
  case "$(uname -s)" in MINGW*|MSYS*|CYGWIN*) return 0 ;; *) return 1 ;; esac
}

# _probe_gh prints the unix path of gh.exe: PATH first, then the folders the
# Windows installers use. A fresh install is often not on this shell's PATH
# yet, and treating that as "not installed" would be a lie.
_probe_gh() {
  local p
  if command -v gh >/dev/null 2>&1; then command -v gh; return 0; fi
  for p in "/c/Program Files/GitHub CLI/gh.exe" \
           "/c/Program Files (x86)/GitHub CLI/gh.exe" \
           "/c/ProgramData/chocolatey/bin/gh.exe" \
           "$HOME/scoop/shims/gh.exe"; do
    if [[ -f "$p" ]]; then printf '%s' "$p"; return 0; fi
  done
  if [[ -n "${LOCALAPPDATA:-}" ]]; then
    p="$(_win2unix "$LOCALAPPDATA")/Microsoft/WinGet/Links/gh.exe"
    if [[ -f "$p" ]]; then printf '%s' "$p"; return 0; fi
  fi
  return 1
}

# _ps "<powershell expression>" runs a snippet with Windows PowerShell, falling
# back to PowerShell 7. Values travel through the environment, never through
# shell quoting, so paths with spaces and backslashes survive intact.
_ps() {
  if command -v powershell.exe >/dev/null 2>&1; then
    powershell.exe -NoProfile -NonInteractive -Command "$1" 2>/dev/null
  elif command -v pwsh.exe >/dev/null 2>&1; then
    pwsh.exe -NoProfile -NonInteractive -Command "$1" 2>/dev/null
  else
    return 127
  fi
}

# get_user_env NAME prints the user-level (HKCU) value of NAME, or nothing.
get_user_env() {
  local name="$1" value=""
  if command -v reg.exe >/dev/null 2>&1; then
    value=$(MSYS2_ARG_CONV_EXCL='*' reg.exe query 'HKCU\Environment' /v "$name" 2>/dev/null \
      | tr -d '\r' | sed -n 's/.*REG_[A-Z_]*[[:space:]]\{1,\}//p') || value=""
  fi
  if [[ -z "$value" ]]; then
    value=$( export WIZARD_NAME="$name"
             _ps "\$v=[Environment]::GetEnvironmentVariable(\$env:WIZARD_NAME,'User'); if (\$v) {[Console]::Out.Write(\$v)}" \
             | tr -d '\r' ) || value=""
  fi
  printf '%s' "$value"
}

# set_user_env NAME VALUE writes a user-level environment variable. setx
# broadcasts WM_SETTINGCHANGE so new processes pick it up; PowerShell is the
# fallback when setx is unavailable.
set_user_env() {
  local name="$1" value="$2"
  if command -v setx.exe >/dev/null 2>&1 \
     && MSYS2_ARG_CONV_EXCL='*' setx.exe "$name" "$value" >/dev/null 2>&1; then
    export "$name=$value"
    return 0
  fi
  if ( export WIZARD_NAME="$name" WIZARD_VALUE="$value"
       _ps "[Environment]::SetEnvironmentVariable(\$env:WIZARD_NAME, \$env:WIZARD_VALUE, 'User')" >/dev/null 2>&1 ); then
    export "$name=$value"
    return 0
  fi
  return 1
}

# append_user_path DIR appends DIR to the user PATH. 0 added, 2 already there,
# 1 failed. Uses PowerShell so %VAR% references stay unexpanded — setx would
# expand them and truncate at 1024 characters.
append_user_path() {
  local dir="$1" current new lower_cur lower_dir rc=0
  current=$( export WIZARD_NAME=Path
             _ps "\$v=[Environment]::GetEnvironmentVariable(\$env:WIZARD_NAME,'User'); if (\$v) {[Console]::Out.Write(\$v)}" \
             | tr -d '\r' ) || current=""
  lower_cur=$(printf '%s' "$current" | tr 'A-Z' 'a-z')
  lower_dir=$(printf '%s' "$dir" | tr 'A-Z' 'a-z')
  case ";$lower_cur;" in *";$lower_dir;"*) return 2 ;; esac
  if [[ -z "$current" ]]; then new="$dir"; else new="$current;$dir"; fi
  ( export WIZARD_VALUE="$new"
    _ps "[Environment]::SetEnvironmentVariable('Path', \$env:WIZARD_VALUE, 'User')" >/dev/null 2>&1 ) || rc=1
  return "$rc"
}

run_wizard() {

TOTAL_STAGES=6

GH_EXE_UNIX=""
GH_EXE_WIN=""
GH_DIR_WIN=""
SET_ENV=()

banner "GitHub CLI for DSH Desktop"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Preflight: what's already on this machine"
say "Reading the current state before changing anything."
say "shell: $(uname -s) · bash ${BASH_VERSION}"

if _is_windows; then
  say "Windows detected (Git Bash). Good."
else
  warn "this wizard targets Windows; the install path probing won't apply elsewhere."
fi

if GH_FOUND=$(_probe_gh); then
  v=$("$GH_FOUND" --version 2>/dev/null || true); v=${v%%$'\n'*}
  say "gh found: $GH_FOUND"
  say "version: ${v:-unknown}"
  if [[ "$GH_FOUND" != "$(command -v gh 2>/dev/null || true)" ]]; then
    note "not on this shell's PATH yet — fine, DSH_GH_PATH points at the file."
  fi
else
  say "gh: not found on PATH or in the usual install folders"
fi

for pm in winget.exe choco.exe scoop.exe; do
  if command -v "$pm" >/dev/null 2>&1; then say "package manager: $pm ✓"; else note "package manager: $pm ✗"; fi
done

cur=$(get_user_env DSH_GH_PATH || true)
if [[ -n "$cur" ]]; then say "DSH_GH_PATH (user): $cur"; else say "DSH_GH_PATH (user): not set"; fi

note "Nothing is written to .env — DSH_GH_PATH is a Windows user variable, not project config."
pause "Enter to continue"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Install GitHub CLI"
say "Trying the package managers in order and stopping at the first success."

if _probe_gh >/dev/null; then
  say "gh is already installed, skipping the installers."
else
  if command -v winget.exe >/dev/null 2>&1; then
    step "winget install GitHub.cli — a UAC prompt may appear, accept it."
    if MSYS2_ARG_CONV_EXCL='*' winget.exe install --id GitHub.cli -e --source winget \
         --accept-package-agreements --accept-source-agreements; then
      say "winget finished."
    else
      warn "winget did not succeed; falling through to the next option."
    fi
  fi

  if ! _probe_gh >/dev/null && command -v choco.exe >/dev/null 2>&1; then
    step "choco install gh -y — needs an elevated shell."
    MSYS2_ARG_CONV_EXCL='*' choco.exe install gh -y >/dev/null 2>&1 \
      && say "choco finished." \
      || warn "choco failed (often because the shell isn't elevated)."
  fi

  if ! _probe_gh >/dev/null && command -v scoop.exe >/dev/null 2>&1; then
    step "scoop install gh"
    scoop.exe install gh >/dev/null 2>&1 && say "scoop finished." || warn "scoop failed."
  fi

  if ! _probe_gh >/dev/null; then
    warn "no installer worked. Install by hand, then come back:"
    open_url "https://cli.github.com/"
    step "Download the Windows MSI, run it, and finish the installer."
    pause "Enter once the installer says it's done"
  fi
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Locate gh.exe and prove it runs"
say "The next stage stores an absolute path, so we need the real file."

if GH_EXE_UNIX=$(_probe_gh); then
  say "found: $GH_EXE_UNIX"
  out=$("$GH_EXE_UNIX" --version 2>/dev/null || true); out=${out%%$'\n'*}
  if [[ -n "$out" ]]; then
    say "runs: $out"
  else
    warn "that file won't run, which usually means a broken install."
    GH_EXE_UNIX=""
  fi
else
  GH_EXE_UNIX=""
fi

if [[ -z "$GH_EXE_UNIX" ]]; then
  GH_EXE_PATH=""
  ask GH_EXE_PATH "Paste the full path to gh.exe (e.g. C:\\Program Files\\GitHub CLI\\gh.exe):" || true
  GH_EXE_PATH="${GH_EXE_PATH%\"}"; GH_EXE_PATH="${GH_EXE_PATH#\"}"
  if [[ -z "$GH_EXE_PATH" ]]; then
    warn "no path given, stopping here."
    exit 1
  fi
  if [[ "$GH_EXE_PATH" =~ ^[A-Za-z]: ]]; then
    GH_EXE_UNIX=$(_win2unix "$GH_EXE_PATH")
  else
    GH_EXE_UNIX="$GH_EXE_PATH"
  fi
  if [[ -f "$GH_EXE_UNIX" ]]; then
    out=$("$GH_EXE_UNIX" --version 2>/dev/null || true); out=${out%%$'\n'*}
    if [[ -n "$out" ]]; then say "runs: $out"; else warn "'$GH_EXE_UNIX' exists but won't run."; fi
  else
    warn "'$GH_EXE_PATH' doesn't exist."
  fi
  if [[ -z "${out:-}" ]]; then
    confirm "Continue anyway?" || { warn "stopping."; exit 1; }
  fi
fi

say "ok: $GH_EXE_UNIX"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Point DSH at gh with DSH_GH_PATH"
GH_EXE_WIN=$(_unix2win "$GH_EXE_UNIX")
say "Windows path: $GH_EXE_WIN"

cur=$(get_user_env DSH_GH_PATH || true)
if [[ "$cur" == "$GH_EXE_WIN" ]]; then
  say "DSH_GH_PATH already points here, nothing to change."
  export DSH_GH_PATH="$GH_EXE_WIN"
else
  if [[ -n "$cur" ]]; then note "current value: $cur"; fi
  if set_user_env DSH_GH_PATH "$GH_EXE_WIN"; then
    say "wrote user environment variable DSH_GH_PATH."
    SET_ENV+=("DSH_GH_PATH=$GH_EXE_WIN")
  else
    warn "couldn't write DSH_GH_PATH automatically."
    step "Set it by hand: Win → 'environment variables' → User variables → New → DSH_GH_PATH."
    SKIPPED+=("DSH_GH_PATH=$GH_EXE_WIN (set it by hand)")
  fi
fi

note "New processes only. DSH Desktop has to be restarted for this to be visible."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Optional: put gh on your user PATH"
say "DSH_GH_PATH is enough for DSH itself. Adding the folder to PATH only makes"
say "'gh' work in every new terminal window."

GH_DIR_WIN="${GH_EXE_WIN%\\*}"
if [[ -z "$GH_DIR_WIN" || "$GH_DIR_WIN" == "$GH_EXE_WIN" ]]; then
  warn "couldn't derive the install folder from '$GH_EXE_WIN', skipping."
else
  if confirm "Add $GH_DIR_WIN to your user PATH?"; then
    rc=0
    append_user_path "$GH_DIR_WIN" || rc=$?
    case "$rc" in
      0) say "appended to user PATH."
         SET_ENV+=("PATH += $GH_DIR_WIN") ;;
      2) say "already on user PATH, nothing to do." ;;
      *) warn "couldn't update PATH; edit it in the Environment Variables dialog." ;;
    esac
  else
    note "skipped — DSH_GH_PATH is what DSH actually reads."
  fi
fi

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Restart DSH Desktop"
say "Environment variables are read once, when a process starts."
step "Quit DSH Desktop completely — including the tray icon."
step "Reopen DSH Desktop."
step "In a new session, ask the agent to run: gh --version"
pause "Enter when you've read this (you can restart later)"

if (( ${#SET_ENV[@]} )); then
  printf '\n'; note "environment variables written:"
  for e in "${SET_ENV[@]}"; do note "  - $e"; done
fi
note "nothing was written to $ENV_FILE (no project config involved)"

finish
}

run_wizard "$@"; exit
